const INFM = {};
INFX.forEach((e, i) => e[0].split("|").forEach((k) => (INFM[k.toLowerCase()] = i)));
const infNorm = (t) =>
  String(t || "")
    .replace(/\s+/g, " ")
    .replace(/[:(·*★].*$/, "")
    .trim()
    .toLowerCase();
let INFR = null,
  INFRI = "";
function infIdx(t) {
  const k = infNorm(t);
  if (!k) return null;
  if (INFM[k] != null) return INFM[k];
  const L = CFG.idi || IDI;
  if (L == "es") return null;
  if (INFRI != L) {
    INFRI = L;
    INFR = {};
    INFX.forEach((e, i) =>
      e[0].split("|").forEach((s) => {
        const x = L == "en" ? trTxt(s) : trX(s);
        if (x && x != s) INFR[infNorm(x)] = i;
      }),
    );
  }
  return INFR[k] != null ? INFR[k] : null;
}
// Pone el «i» al lado de cada etiqueta que tiene ayuda
function infDeco(root) {
  if (!root) return;
  root.querySelectorAll("label.m, h3, div.m, .k > b").forEach((el) => {
    if (el.dataset.inf) return;
    el.dataset.inf = "0";
    if (el.closest("button, .ch, select, a, summary, .lzc, #inf-p")) return;
    if (el.tagName == "DIV" && (el.children.length > 2 || el.textContent.length > 60)) return;
    const n = el.firstChild,
      t = n && n.nodeType == 3 ? n.nodeValue : el.textContent,
      d = t.indexOf(":");
    if (d > 0 && /[A-Za-zÀ-ÿ]/.test(t.slice(d + 1))) return;
    const i = infIdx(t);
    if (i == null || (INFX[i][3] && root.id != INFX[i][3])) return;
    el.dataset.inf = "1";
    const nota = infNota(el);
    if (nota) nota.classList.add("inf-oc");
    el.insertAdjacentHTML("beforeend", ` <button class="inf" data-a="inf" data-v="${i}" aria-label="${["Qué es", "What is it", "Qu'est-ce que c'est", "O que é"][INFL[CFG.idi] || 0]}">i</button>`);
  });
}
const INFL = { es: 0, en: 1, fr: 2, pt: 3 };
// Si la etiqueta ya tenía una nota del juego, se une a la ayuda para no repetir el símbolo
function infNota(el) {
  const c = [el.nextElementSibling, el.parentElement && el.parentElement.classList.contains("k") ? el.parentElement.nextElementSibling : null];
  return c.find((x) => x && x.matches && x.matches("details.nota")) || null;
}
function infCierra() {
  const p = document.getElementById("inf-p");
  if (!p || p.style.display == "none") return false;
  p.style.display = "none";
  return true;
}
ACT["inf"] = (v, el) => {
  const e = INFX[+v];
  if (!e) return;
  const L = INFL[CFG.idi] || 0;
  let p = document.getElementById("inf-p");
  if (!p) {
    p = document.createElement("div");
    p.id = "inf-p";
    p.setAttribute("role", "dialog");
    document.body.appendChild(p);
    p.addEventListener("click", infCierra);
  }
  const n = el && el.parentElement && el.parentElement.firstChild,
    titulo = (n && n.nodeType == 3 && n.nodeValue.trim() ? n.nodeValue : e[0].split("|")[0]).replace(/[:(·*★].*$/, "").trim();
  const nota = el && el.parentElement ? infNota(el.parentElement) : null,
    nt = nota ? nota.textContent.trim() : "";
  p.innerHTML = `<div class="inf-c"><div class="inf-t"><b>${esc(titulo)}</b><span aria-hidden="true">×</span></div><p>${esc(e[1][L] || e[1][0])}</p>${nt ? `<p class="inf-n">${esc(nt)}</p>` : ""}<p class="inf-d"><b>${["Dato curioso", "Fun fact", "Le saviez-vous ?", "Curiosidade"][L]}</b> ${esc(e[2][L] || e[2][0])}</p></div>`;
  p.style.display = "flex";
};
document.addEventListener("keydown", (e) => {
  if (e.key == "Escape" && infCierra()) e.stopImmediatePropagation();
}, true);
if (typeof window != "undefined") {
  const atr = window.atrasAndroid;
  window.atrasAndroid = function () {
    if (infCierra()) return true;
    return typeof atr == "function" ? atr.apply(this, arguments) : false;
  };
}
let INFQ = 0;
if (typeof MutationObserver != "undefined" && document.body)
  new MutationObserver(() => {
    if (!INFQ)
      INFQ = requestAnimationFrame(() => {
        INFQ = 0;
        infDeco(document.getElementById("md"));
        infDeco(document.getElementById("app"));
      });
  }).observe(document.body, { childList: true, subtree: true });
